{
  "name": "resolve-realpath",
  "version": "1.0.0",
  "description": "Resolve symlinks in a file path down to its real, canonical filesystem path",
  "type": "module",
  "main": "src/realpath.js",
  "bin": {
    "resolve-realpath": "bin/cli.js"
  },
  "files": [
    "src",
    "bin"
  ],
  "engines": {
    "node": ">=12"
  },
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "license": "MIT"
}

import fs from "node:fs";

const realpathSync = fs.realpathSync;

const nativeRealpath =
  typeof realpathSync.native === "function" ? realpathSync.native : null;

export function resolveRealPath(inputPath) {
  if (typeof inputPath !== "string" || inputPath.length === 0) {
    throw new TypeError("resolveRealPath expects a non-empty string path");
  }

  if (nativeRealpath) {
    try {
      return nativeRealpath(inputPath);
    } catch (err) {
      if (!isFallbackWorthy(err)) {
        throw err;
      }
    }
  }

  return realpathSync(inputPath);
}

function isFallbackWorthy(err) {
  return err && (err.code === "ENOENT" || err.code === "EINVAL");
}

export default resolveRealPath;

#!/usr/bin/env node
import { resolveRealPath } from "../src/realpath.js";

const target = process.argv[2];

if (!target) {
  process.stderr.write("Usage: resolve-realpath <path>\n");
  process.exit(1);
}

try {
  process.stdout.write(`${resolveRealPath(target)}\n`);
} catch (err) {
  process.stderr.write(`${err.message}\n`);
  process.exit(1);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import { resolveRealPath } from "../src/realpath.js";

test("resolves a symlink to its canonical target", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "resolve-realpath-"));
  const real = path.join(dir, "real");
  const link = path.join(dir, "link");
  fs.mkdirSync(real);
  fs.writeFileSync(path.join(real, "file.txt"), "hi");
  fs.symlinkSync(real, link);

  assert.equal(resolveRealPath(path.join(link, "file.txt")), path.join(real, "file.txt"));
});

test("rejects a non-string path", () => {
  assert.throws(() => resolveRealPath(null), TypeError);
});
